// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, uint256 ts2) public {
        // keep both timestamps well above the (small) block number
        vm.roll(2);
        ts1 = bound(ts1, 3, type(uint64).max);
        ts2 = bound(ts2, 3, type(uint64).max);
        vm.assume(ts1 > ts2);

        vm.deal(address(this), 20 ether);

        // first call at the larger timestamp
        vm.warp(ts1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // a later-in-time attempt with a SMALLER timestamp must be rejected:
        // reference stored pastBlockTime = ts1, so require(ts2 > ts1) fails.
        vm.warp(ts2);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // the mutant stored block.number (tiny) instead of ts1, so ts2 > pastBlockTime
        // holds and the second call succeeds there.
        assertTrue(!ok2);
    }
}
